TOURS = [{"slug":"cataileauxcerf-details","name":"CATAMARAN CRUISE TO ILE AUX CERFS ISLAND","summary":"*Including BBQ Lunch, Drinks, Snorkeling & Waterfall Visit","description":"Set sail on a captivating catamaran cruise to the breathtaking Ile aux Cerfs Island , a true gem off the east coast of Mauritius. This shared tour offers an exciting blend of exploration and relaxation, with panoramic coastal views, snorkeling in vibrant coral reefs (equipment available onboard or bring your own), and a visit to the majestic Grand River South East Waterfall. Enjoy a sumptuous BBQ buffet lunch featuring meats, salads, and vegetarian options upon request, all while sipping unlimited soft and alcoholic drinks in a lively, friendly atmosphere. Whether you're lounging on sun decks or mingling with fellow travelers, this island escape offers the perfect tropical experience. Your journey begins at Pointe Jerome, where our luxury catamarans offer comfort, safety, and spacious decks for your enjoyment. Photography is welcome, and our professional crew ensures a safe and seamless cruise, even for beginners trying snorkeling for the first time. Please note that additional water sports like parasailing and undersea walking are not included in this package. We maintain a flexible cancellation policy, uphold eco-friendly practices, and offer full refunds for weather-related cancellations. For a memorable day in paradise, book your catamaran cruise with MauRide!","image_url":"https://marideal-partners-prod.s3.ap-southeast-1.amazonaws.com/public/deals/9852/images/9852_gY_DESK_PDP_M.jpg","duration_minutes":420,"price_cents":8400,"currency":"EUR","area":"East Coast","category_key":"sea","adult_price_cents":6600,"child_price_cents":3400,"baby_price_label":"FREE","included_items":["Snorkelling","BBQ buffet lunch","Soft drinks & alcoholic drinks","Grand River South East waterfall"],"excluded_items":["Transport (available separately)","Water activities","Private cruise"],"itinerary":["Pointe Jero